// 获取衡石返回数据
const response = $input.item.json;
const schema = response.data.schema;
const rows = response.data.data;

// 提取列名（用 label 作为表头）
const headers = schema.map(field => field.label);

// 将二维数组转换为对象数组
const tableData = rows.map(row => {
  const obj = {};
  headers.forEach((header, index) => {
    let val = row[index];
    // 达成率字段转为百分比字符串，方便阅读
    if (header.includes('达成率') && val !== null && val !== undefined) {
      val = (val * 100).toFixed(2) + '%';
    }
    obj[header] = val ?? '-';
  });
  return obj;
});

return tableData;

// ========== 获取数据 ==========
const tableData = $input.all().map(item => item.json);
const gmvRow = tableData.find(row => row['idx'] === 'GMV');

// ========== 提取字段值（单位：元 → 万，保留2位小数）==========
const toWan = (val) => (parseFloat(val) / 10000).toFixed(2);

const 成衣目标 = toWan(gmvRow['成衣目标']);
const 成衣实际 = toWan(gmvRow['成衣实际']);
const 成衣达成率Raw = parseFloat(gmvRow['成衣达成率']);
const 成衣达成率 = 成衣达成率Raw > 1 ? 成衣达成率Raw / 100 : 成衣达成率Raw;

const 一部目标 = toWan(gmvRow['成衣一部目标']);
const 一部实际 = toWan(gmvRow['成衣一部实际']);
const 一部达成率Raw = parseFloat(gmvRow['成衣一部达成率']);
const 一部达成率 = 一部达成率Raw > 1 ? 一部达成率Raw / 100 : 一部达成率Raw;

const 二部目标 = toWan(gmvRow['成衣二部目标']);
const 二部实际 = toWan(gmvRow['成衣二部实际']);
const 二部达成率Raw = parseFloat(gmvRow['成衣二部达成率']);
const 二部达成率 = 二部达成率Raw > 1 ? 二部达成率Raw / 100 : 二部达成率Raw;

// ========== 从表单获取时间进度参数（改为手动输入）==========
const formData = $('参数填写表单 - On form submission').item.json;
const monthStr = formData['月份'];
const [year, month] = monthStr.split('-').map(Number);

const T1 = parseInt(formData['T-1的天数']);           // 用户输入，如 29
const daysInMonth = parseInt(formData['所选月总天数']); // 用户输入，如 31

const timeProgress = T1 / daysInMonth;
const timeProgressPct = (timeProgress * 100).toFixed(2) + '%';

// ========== 辅助函数 ==========
const pct = (val) => (val * 100).toFixed(2) + '%';
const gapText = (rate) => {
  const diff = ((timeProgress - rate) * 100).toFixed(2);
  return parseFloat(diff) > 0
    ? `落后时间进度${diff}%`
    : `超额时间进度${Math.abs(diff)}%`;
};
const statusText = (rate) => rate >= timeProgress
  ? '属于超额完成状态'
  : '属于未达标状态，请重点关注';
const shortfallText = (target, actual) => {
  const diff = (parseFloat(target) - parseFloat(actual)).toFixed(2);
  return parseFloat(diff) > 0
    ? `，差额${diff}万`
    : `，超额${Math.abs(diff)}万`;
};
const proportion = (part, total) =>
  ((parseFloat(part) / parseFloat(total)) * 100).toFixed(2) + '%';

// ========== 生成文字 ==========
const lines = [
  `1.1、${month}月整体指标跟进（截止${month}月${T1}日，时间进度${timeProgressPct}）`,
  `1. 成衣：${month}月GMV目标${成衣目标}万，截止到${month}月${T1}日，完成${成衣实际}万，完成率${pct(成衣达成率)}，${gapText(成衣达成率)}${shortfallText(成衣目标, 成衣实际)}`,
  `2. 成衣一部：${month}月GMV目标${一部目标}万，截止到${month}月${T1}日，完成${一部实际}万，完成率${pct(一部达成率)}，${gapText(一部达成率)}${shortfallText(一部目标, 一部实际)}，GMV占比${proportion(一部实际, 成衣实际)}`,
  `3. 成衣二部：${month}月GMV目标${二部目标}万，截止到${month}月${T1}日，完成${二部实际}万，完成率${pct(二部达成率)}，${gapText(二部达成率)}${shortfallText(二部目标, 二部实际)}，GMV占比${proportion(二部实际, 成衣实际)}`,
  ``,
  `结论：`,
  `截止到${month}月${T1}日，成衣整体目标完成率${pct(成衣达成率)}，${gapText(成衣达成率)}，${statusText(成衣达成率)}`,
  `截止到${month}月${T1}日，成衣一部整体目标完成率${pct(一部达成率)}，${gapText(一部达成率)}，${statusText(一部达成率)}`,
  `截止到${month}月${T1}日，成衣二部整体目标完成率${pct(二部达成率)}，${gapText(二部达成率)}，${statusText(二部达成率)}`
];

return lines.map(line => ({ line }));

// （API URL+Access Token+月份_参数+目标类型_参数）
const month = $('参数填写表单 - On form submission').item.json['月份'];
const token = $('获取衡石Access Token - HTTP Request').item.json['access_token'];

// 手动拼接 URL，不让 N8N 自动 encode
const url = `https://hengshi.kapeixi.cn/api/open/pc_gmv_kpi?access_token=${token}&月份=${month}&目标类型=正常目标`;

return { request_url: url };

const monthStr = $('参数填写表单 - On form submission').item.json['月份'];
const T1 = parseInt($('参数填写表单 - On form submission').item.json['T-1的天数']);
const token = $('获取衡石Access Token - HTTP Request').item.json['access_token'];

const startDate = `${monthStr}-01`;
const endDate = `${monthStr}-${String(T1).padStart(2, '0')}`;

const url = `https://hengshi.kapeixi.cn/api/open/pc_week_report_scene_age_success_rate?access_token=${token}&01K596W8QTSC33RMDSRWA8HM8M=${startDate},${endDate}`;

return { request_url: url };

const input = $input.all()[0].json;

// 衡石真实数据路径：data.data 才是数据行
const dataRows = input.data.data;
const schema = input.data.schema;

// 格式化函数
const fmtNum = (num) => {
  if (num === null || num === undefined) return '-';
  return Number(num).toLocaleString('zh-CN', { maximumFractionDigits: 2 });
};

const fmtPercent = (num) => {
  if (num === null || num === undefined) return '-';
  return (num * 100).toFixed(2) + '%';
};

// 把14行数据整理成对象，方便后续引用
const result = {};
dataRows.forEach(row => {
  const metricName = row[0]; // 第一列是指标名：GMV、新品GMV...
  result[metricName] = {
    month: row[1],                    // 月份
    allTarget: fmtNum(row[2]),        // 全品类目标
    allActual: fmtNum(row[3]),        // 全品类实际
    allRate: fmtPercent(row[4]),      // 全品类达成率
    swimProductTarget: fmtNum(row[5]),    // 泳衣产品部目标
    swimProductActual: fmtNum(row[6]),    // 泳衣产品部实际
    swimProductRate: fmtPercent(row[7]),  // 泳衣产品部达成率
    swimBuyerTarget: fmtNum(row[8]),      // 泳衣买手部目标
    swimBuyerActual: fmtNum(row[9]),      // 泳衣买手部实际
    swimBuyerRate: fmtPercent(row[10]),   // 泳衣买手部达成率
    swimTarget: fmtNum(row[11]),          // 泳衣目标
    swimActual: fmtNum(row[12]),          // 泳衣实际
    swimRate: fmtPercent(row[13]),        // 泳衣达成率
    cloth1Target: fmtNum(row[14]),        // 成衣一部目标
    cloth1Actual: fmtNum(row[15]),        // 成衣一部实际
    cloth1Rate: fmtPercent(row[16]),      // 成衣一部达成率
    cloth2Target: fmtNum(row[17]),        // 成衣二部目标
    cloth2Actual: fmtNum(row[18]),        // 成衣二部实际
    cloth2Rate: fmtPercent(row[19]),      // 成衣二部达成率
    brandTarget: fmtNum(row[20]),         // 品牌设计部目标
    brandActual: fmtNum(row[21]),         // 品牌设计部实际
    brandRate: fmtPercent(row[22]),       // 品牌设计部达成率
    newChannelTarget: fmtNum(row[23]),    // 新渠道产品部目标
    newChannelActual: fmtNum(row[24]),    // 新渠道产品部实际
    newChannelRate: fmtPercent(row[25]),  // 新渠道产品部达成率
    clothTarget: fmtNum(row[26]),         // 成衣目标
    clothActual: fmtNum(row[27]),         // 成衣实际
    clothRate: fmtPercent(row[28]),       // 成衣达成率
    sleepTarget: fmtNum(row[29]),         // 内睡目标
    sleepActual: fmtNum(row[30]),         // 内睡实际
    sleepRate: fmtPercent(row[31]),       // 内睡达成率
    accTarget: fmtNum(row[32]),           // acc目标
    accActual: fmtNum(row[33]),           // acc实际
    accRate: fmtPercent(row[34]),         // acc达成率
    shapeTarget: fmtNum(row[35]),         // 塑身衣项目部目标
    shapeActual: fmtNum(row[36]),         // 塑身衣项目部实际
    shapeRate: fmtPercent(row[37]),       // 塑身衣项目部达成率
  };
});

return [{
  json: {
    month: dataRows[0][1],  // 月份：2026-07
    updateTime: $now.toFormat('yyyy-MM-dd HH:mm'),
    // 核心指标速览
    gmv: result['GMV'],
    newProductGmv: result['新品GMV'],
    newCount: result['上新数'],
    successCount: result['成功数'],
    hotCount: result['爆款数'],
    bigHotCount: result['大爆款数'],
    superHotCount: result['超爆款数'],
    successRate: result['成功率'],
    hotRate: result['爆款率'],
    newProductAvgCost: result['新品款均成本'],
    newProductEfficiency: result['新品款效'],
    // 完整原始数据（备用）
    raw: result
  }
}];

const SHEET_NAME = '推送明细';

const header = [
  'month_str', 'skc', '图片链接', '首次上架时间',
  '设计师名', '业务部门', '当月是否在架', '在架天数', '提前下架',
];

const toCell = (v) => (typeof v === 'boolean' ? String(v) : v);

const rows = $input.all().map((item) => ({
  month_str: item.json.month_str,
  skc: item.json.skc,
  图片链接: item.json['图片链接'],
  首次上架时间: item.json['首次上架时间'],
  //设计师名: item.json['设计师名'],
  设计师名:"初人豪",
  业务部门: item.json['业务部门'],
  当月是否在架: item.json['当月是否在架'],
  在架天数: item.json['在架天数'],
  // 提前下架: String(item.json['提前下架']), // 测完别再写死 
  提前下架:String(true)
}));

const dataRows = rows.map((r) => [
  r.month_str, r.skc, r.图片链接, r.首次上架时间,
  r.设计师名, r.业务部门, r.当月是否在架, r.在架天数, r.提前下架,
].map(toCell));

const values = [header, ...dataRows];
const valueRows = values.length;

const sheetsResp = $('获取工作表').first().json;
const sheets = sheetsResp?.data?.sheets || sheetsResp?.sheets || [];
const sheet = sheets.find((s) => (s.title || s.sheet?.title) === SHEET_NAME);
if (!sheet) throw new Error(`找不到工作表「${SHEET_NAME}」`);

const sheetId = sheet.sheet_id || sheet.sheetId;
const rowCount = sheet.grid_properties?.row_count || sheet.rowCount || 0;

const needClear = rowCount > valueRows;
const clearStartIndex = valueRows; // 与你们删行节点口径一致；1 起闭区间再按节点改
const clearEndIndex = rowCount;

const spreadsheetToken = $('获取电子表格信息').first().json?.data?.spreadsheet?.token;

return [{
  json: {
    spreadsheetToken,
    sheetId,
    sheetName: SHEET_NAME,
    rowCount,
    valueRows,
    needClear,
    clearStartIndex,
    clearEndIndex,
    values,
    rows, // 筛提前下架用这个
  },
}];

const item = $('筛提前下架行').item.json;
const resp = $input.first().json;
const employees = resp?.data?.employees || [];

const wanted = String(item.designerName || '').trim();
const normalize = (s) => String(s || '').trim();

let openId = '';
let matchedName = '';
for (const emp of employees) {
  const base = emp.base_info || emp.baseInfo || {};
  const nameObj = base.name?.name || base.name || {};
  const candidates = [
    nameObj.default_value,
    nameObj.defaultValue,
    nameObj.i18n_value?.zh_cn,
    nameObj.i18nValue?.zh_cn,
    base.name?.another_name,
    typeof base.name === 'string' ? base.name : '',
  ].map(normalize).filter(Boolean);

  const hit = candidates.find((n) => n === wanted) || candidates.find((n) => n.includes(wanted) || wanted.includes(n));
  if (hit) {
    openId = base.employee_id || base.employeeId || emp.open_id || '';
    matchedName = hit;
    break;
  }
}

if (!openId && employees.length === 1) {
  const base = employees[0].base_info || employees[0].baseInfo || {};
  openId = base.employee_id || base.employeeId || '';
  matchedName = base.name?.name?.default_value || wanted;
}

if (!openId) {
  return [];
}

return [{
  json: {
    ...item,
    openId,
    matchedName,
    receive_id: openId,
  },
}];

const prepared = $('解析数据').first().json;
const rows = prepared.rows || [];
const isTrue = (v) => v === true || v === 'true' || v === 'TRUE' || v === 1 || v === '1';
const CHUNK = 10;

const alerts = rows.filter((r) => isTrue(r.提前下架));
if (!alerts.length) return [];

const byDesigner = new Map();
for (const r of alerts) {
  const name = String(r.设计师名 || '').trim();
  if (!name) continue;
  if (!byDesigner.has(name)) byDesigner.set(name, []);
  byDesigner.get(name).push(r);
}

const out = [];
for (const [designerName, list] of byDesigner.entries()) {
  const total = list.length;
  const batches = Math.ceil(total / CHUNK);
  for (let i = 0; i < batches; i++) {
    const chunk = list.slice(i * CHUNK, (i + 1) * CHUNK);
    out.push({
      json: {
        designerName,
        alerts: chunk,
        skcList: chunk.map((x) => x.skc).filter(Boolean),
        batchIndex: i + 1,
        batchTotal: batches,
        totalCount: total,
        spreadsheetToken: prepared.spreadsheetToken,
        sheetName: prepared.sheetName,
      },
    });
  }
}
return out;

const r = $json;
const at = `<at id=${r.openId}></at>`;
const alerts = r.alerts || [];
const batchIndex = r.batchIndex || 1;
const batchTotal = r.batchTotal || 1;
const totalCount = r.totalCount || alerts.length;
const designer = r.designerName || r.matchedName || '';

const sheetUrl =
  r.sheetUrl ||
  $('获取电子表格信息').first().json?.data?.spreadsheet?.url ||
  (r.spreadsheetToken
    ? `https://mycupshe.feishu.cn/sheets/${r.spreadsheetToken}`
    : '');

const title =
  batchTotal > 1
    ? `无库存测试款推送（${totalCount} 条 · ${batchIndex}/${batchTotal}）`
    : `无库存测试款推送（${totalCount} 条）`;

const intro = [
  sheetUrl
    ? `${at} 您好，这是每日无库存测试款推送明细：[打开明细表](${sheetUrl})`
    : `${at} 您好，这是每日无库存测试款推送明细。`,
  '',
  '以下 SKC 为**提前下架**，请尽快确认：',
  batchTotal > 1 ? `（本卡第 ${batchIndex}/${batchTotal} 组，每组最多 10 条）` : '',
].filter((x) => x !== '').join('\n');

const tableRows = alerts.map((a) => ({
  skc: String(a.skc ?? ''),
  month: String(a.月 || a.month_str || ''),
  firstOn: String(a.首次上架时间 || ''),
  sales: String(a.销售额 ?? ''),
  img: a.图片链接 || '',
}));

const card = {
  config: { wide_screen_mode: true },
  header: {
    template: 'orange',
    title: { tag: 'plain_text', content: title },
  },
  elements: [
    {
      tag: 'div',
      text: { tag: 'lark_md', content: intro },
    },
    { tag: 'hr' },
    {
      tag: 'table',
      page_size: 10,
      row_height: 'low',
      header_style: {
        text_align: 'left',
        text_size: 'normal',
        background_style: 'grey',
        text_color: 'default',
        bold: true,
        lines: 1,
      },
      columns: [
        { name: 'month', display_name: '月', data_type: 'text', width: 'auto' },
        { name: 'skc', display_name: 'SKC', data_type: 'text', width: 'auto' },

        { name: 'firstOn', display_name: '首次上架', data_type: 'text', width: 'auto' },
        { name: 'sales', display_name: '销售额', data_type: 'text', width: 'auto' },
        { name: 'img', display_name: '图片', data_type: 'lark_md', width: 'auto' },
      ],
      rows: tableRows.map((row) => ({
        ...row,
        img: row.img ? `[查看图片](${row.img})` : '-',
      })),
    },
  ],
};



return [{
  json: {
    ...r,
    sheetUrl,
    receive_id: r.openId,
    msg_type: 'interactive',
    content: JSON.stringify(card),
    dedupeKey: `${String(r.openId || '').slice(-8)}-b${batchIndex}-${Date.now()}`.slice(0, 50),
  },
}];

const OPEN_IDS = [
  'ou_70ba85c025a9704006240e313969c0b1',
  // 'ou_xxxxxxxx',
];

const r = $json;
const alerts = r.alerts || [];
const batchIndex = r.batchIndex || 1;
const batchTotal = r.batchTotal || 1;
const totalCount = r.totalCount || alerts.length;

const sheetUrl =
  r.sheetUrl ||
  $('获取电子表格信息').first().json?.data?.spreadsheet?.url ||
  (r.spreadsheetToken
    ? `https://mycupshe.feishu.cn/sheets/${r.spreadsheetToken}`
    : '');

const title =
  batchTotal > 1
    ? `提前下架提醒（${totalCount} 条 · ${batchIndex}/${batchTotal}）`
    : `提前下架提醒（${totalCount} 条）`;

const tableRows = alerts.map((a) => ({
  designer: String(a.设计师名 || a.designerName || ''),
  skc: String(a.skc ?? ''),
  month: String(a.月 || a.month_str || ''),
  firstOn: String(a.首次上架时间 || ''),
  sales: String(a.销售额 ?? ''),
  img: a.图片链接 || '',
}));

const buildCard = (openId) => {
  const at = `<at id=${openId}></at>`;
  const intro = [
    sheetUrl
      ? `${at} 您好，这是每日无库存测试款推送明细：[打开明细表](${sheetUrl})`
      : `${at} 您好，这是每日无库存测试款推送明细。`,
    '',
    '以下 SKC 为**提前下架**，请尽快确认：',
    batchTotal > 1 ? `（本卡第 ${batchIndex}/${batchTotal} 组，每组最多 10 条）` : '',
  ].filter((x) => x !== '').join('\n');

  return {
    config: { wide_screen_mode: true },
    header: {
      template: 'orange',
      title: { tag: 'plain_text', content: title },
    },
    elements: [
      { tag: 'div', text: { tag: 'lark_md', content: intro } },
      { tag: 'hr' },
      {
        tag: 'table',
        page_size: 10,
        row_height: 'low',
        header_style: {
          text_align: 'left',
          text_size: 'normal',
          background_style: 'grey',
          text_color: 'default',
          bold: true,
          lines: 1,
        },
        columns: [
          { name: 'designer', display_name: '设计师', data_type: 'text', width: 'auto' },
          { name: 'month', display_name: '月', data_type: 'text', width: 'auto' },
          { name: 'skc', display_name: 'SKC', data_type: 'text', width: 'auto' },
          { name: 'firstOn', display_name: '首次上架', data_type: 'text', width: 'auto' },
          { name: 'sales', display_name: '销售额', data_type: 'text', width: 'auto' },
          { name: 'img', display_name: '图片', data_type: 'lark_md', width: 'auto' },
        ],
        rows: tableRows.map((row) => ({
          ...row,
          img: row.img ? `[查看图片](${row.img})` : '-',
        })),
      },
    ],
  };
};

return OPEN_IDS.map((openId) => {
  const card = buildCard(openId);
  return {
    json: {
      ...r,
      sheetUrl,
      openId,
      receive_id: openId,
      msg_type: 'interactive',
      content: JSON.stringify(card),
      dedupeKey: `${String(openId).slice(-8)}-b${batchIndex}-${Date.now()}`.slice(0, 50),
    },
  };
});
